#version 460
#extension GL_GOOGLE_include_directive : require
#include "pelican_sets.glsl"
#include "pelican_frame.glsl"
#undef PELICAN_FEATURE_CLUSTERED_LIGHTING
#include "pelican_lighting_v1.glsl"

// GB-3 B: the Deferred lighting template (New... > Deferred lighting), its
// light loop replaced by one rectangular area light evaluated with linearly
// transformed cosines (Heitz et al. 2016).
//
// Where the light's values come from: the rectangle's corners are constants
// here (the Graph tab could not hand a pass a value: see the report); its
// radiance is the scene's first directional light (KeyLight) colour times its
// intensity, so the Inspector's Intensity changes it. The fitted LTC tables
// (two 64 x 64 images) are not used: the engine has no way to load an image
// file into a render target. The GGX lobe is stood in for by a normalised
// clamped cosine about the mirror direction, M^-1 = diag(1/a, 1/a, 1).

layout(location = 0) in vec2 inUV;
layout(location = 0) out vec4 outColor;

PELICAN_DECLARE_INPUT_0(in_albedo);
PELICAN_DECLARE_INPUT_1(in_normal);
PELICAN_DECLARE_INPUT_2(in_material);
PELICAN_DECLARE_INPUT_3(in_worldpos);
PELICAN_DECLARE_INPUT_4(in_emissive);

// The light: a 1.5 x 1.0 rectangle standing at z = 4, right of the box,
// facing the camera (-z). Wound so that cross(q1 - q0, q3 - q0) is +z.
const vec3 LIGHT_Q0 = vec3(1.0, 0.2, 4.0);
const vec3 LIGHT_Q1 = vec3(2.5, 0.2, 4.0);
const vec3 LIGHT_Q2 = vec3(2.5, 1.2, 4.0);
const vec3 LIGHT_Q3 = vec3(1.0, 1.2, 4.0);
// A polished floor, so the reflection keeps the light's shape.
const float MAX_ROUGHNESS = 0.1;

// GB-3 B: the LTC area light (Heitz et al. 2016), without the fitted tables.
// The GGX lobe is stood in for by a clamped cosine around the mirror direction,
// narrowed by the roughness: M^-1 = diag(1/a, 1/a, 1) in a frame whose z is the
// reflection. The diffuse term is the exact one (M = identity in the normal
// frame). The polygon is not clipped to the horizon (the "no clipping" form);
// a negative sum is clamped.

float ltc_edge(vec3 v1, vec3 v2) {
    float x = clamp(dot(v1, v2), -0.9999, 0.9999);
    float theta = acos(x);
    vec3 c = cross(v1, v2);
    return theta * c.z / max(length(c), 1e-6);
}

// The four corners, already in the lobe's frame (any scale): the form factor
// of the quad as a clamped cosine sees it. Wound so that cross(p1 - p0, p3 - p0)
// points away from the lit side (the light shines the other way).
float ltc_quad(vec3 p0, vec3 p1, vec3 p2, vec3 p3) {
    vec3 v0 = normalize(p0), v1 = normalize(p1), v2 = normalize(p2), v3 = normalize(p3);
    float sum = ltc_edge(v0, v1) + ltc_edge(v1, v2) + ltc_edge(v2, v3) + ltc_edge(v3, v0);
    return max(sum / (2.0 * 3.14159265359), 0.0);
}

mat3 ltc_frame(vec3 z) {
    vec3 up = abs(z.y) < 0.99 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
    vec3 x = normalize(cross(up, z));
    vec3 y = cross(z, x);
    return transpose(mat3(x, y, z));
}

// What a quad light (corners q0..q3, radiance L) gives a point with normal n
// seen from v (toward the eye), albedo and F0, roughness r.
vec3 ltc_area_light(vec3 position, vec3 n, vec3 v, vec3 diffuse_color, vec3 f0, float roughness,
                    vec3 q0, vec3 q1, vec3 q2, vec3 q3, vec3 radiance) {
    // one-sided: nothing behind the light
    if (dot(cross(q1 - q0, q3 - q0), position - q0) >= 0.0) return vec3(0.0);
    // diffuse: the clamped cosine about n
    mat3 tn = ltc_frame(n);
    float diffuse = ltc_quad(tn * (q0 - position), tn * (q1 - position), tn * (q2 - position),
                             tn * (q3 - position));
    // specular: a clamped cosine about the mirror direction, a = roughness^2
    vec3 r = reflect(-v, n);
    mat3 tr = ltc_frame(r);
    float a = max(roughness * roughness, 0.02);
    mat3 minv = mat3(1.0 / a, 0.0, 0.0, 0.0, 1.0 / a, 0.0, 0.0, 0.0, 1.0);
    mat3 m = minv * tr;
    float specular = ltc_quad(m * (q0 - position), m * (q1 - position), m * (q2 - position),
                              m * (q3 - position));
    float n_dot_v = clamp(dot(n, v), 0.0, 1.0);
    vec3 fresnel = f0 + (1.0 - f0) * pow(1.0 - n_dot_v, 5.0);
    return radiance * (diffuse_color * diffuse + fresnel * specular);
}

// The light itself, seen from the camera: the rectangle where a view ray
// meets it before the G-buffer's surface.
float light_seen(vec3 origin, vec3 direction, float surface_distance) {
    vec3 n = normalize(cross(LIGHT_Q1 - LIGHT_Q0, LIGHT_Q3 - LIGHT_Q0));
    float denominator = dot(direction, n);
    if (abs(denominator) < 1e-5) return 0.0;
    float t = dot(LIGHT_Q0 - origin, n) / denominator;
    if (t <= 0.0 || t > surface_distance) return 0.0;
    vec3 p = origin + t * direction - LIGHT_Q0;
    vec3 u = LIGHT_Q1 - LIGHT_Q0, v = LIGHT_Q3 - LIGHT_Q0;
    float a = dot(p, u) / dot(u, u), b = dot(p, v) / dot(v, v);
    return (a >= 0.0 && a <= 1.0 && b >= 0.0 && b <= 1.0) ? 1.0 : 0.0;
}

void main() {
    vec3 albedo = PELICAN_TEXTURE_2D_0(in_albedo, inUV).rgb;
    vec3 normal_encoded = PELICAN_TEXTURE_2D_1(in_normal, inUV).rgb;
    vec4 material = PELICAN_TEXTURE_2D_2(in_material, inUV);
    vec3 world_position = PELICAN_TEXTURE_2D_3(in_worldpos, inUV).rgb;
    vec3 emissive = PELICAN_TEXTURE_2D_4(in_emissive, inUV).rgb;

    vec3 radiance = vec3(0.0);
    if (pelicanLights.directionalLightCount > 0u)
        radiance = pelicanLights.directionalLights[0].color *
                   pelicanLights.directionalLights[0].intensity * 0.5;

    vec4 far = inverse(pelicanFrame.projection * pelicanFrame.view) *
               vec4(inUV * 2.0 - 1.0, 1.0, 1.0);
    vec3 eye = pelicanFrame.camera_position.xyz;
    vec3 ray = normalize(far.xyz / far.w - eye);

    // The geometry pass leaves the normal at zero where it drew nothing.
    if (all(equal(normal_encoded, vec3(0.0)))) {
        outColor = vec4(emissive + radiance * light_seen(eye, ray, 1e9), 1.0);
        return;
    }
    vec3 normal = normalize(normal_encoded * 2.0 - 1.0);
    float roughness = clamp(material.r, 0.04, MAX_ROUGHNESS);
    float metallic = clamp(material.g, 0.0, 1.0);
    vec3 to_camera = normalize(eye - world_position);
    vec3 diffuse_color = albedo * (1.0 - metallic);
    vec3 f0 = mix(vec3(0.04), albedo, metallic);

    vec3 color = emissive + diffuse_color * material.b * pelican_env_ambient(normal);
    color += ltc_area_light(world_position, normal, to_camera, diffuse_color, f0, roughness,
                            LIGHT_Q0, LIGHT_Q1, LIGHT_Q2, LIGHT_Q3, radiance);
    color += radiance * light_seen(eye, ray, distance(eye, world_position));
    outColor = vec4(color, 1.0);
}
